from test_party_plans import tests,raid
from test_bufftap import test
from test_blessings import setup

test('Roster event refreshes the open player editor to the replacement GUID',setup+"BuffTap:Options(); local f=BuffTap.options; f.selectTab(2); f.expandedBlessing='WARRIOR'; BuffTap:Options(); local prior=UnitGUID; UnitGUID=function(u) return u=='party1' and 'Player-new-member' or prior(u) end; BuffTap.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); assert(f.blessingPlayerRows[1].guid=='Player-new-member')")
test('Roster event removes a departed player row',setup+"BuffTap:Options(); local f=BuffTap.options; f.selectTab(2); f.expandedBlessing='WARRIOR'; BuffTap:Options(); local exists=UnitExists; UnitExists=function(u) return u~='party1' and exists(u) end; BuffTap.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); assert(not f.blessingDetail.shown and not f.blessingPlayerRows[1].entry)")
test('Roster event updates Salvation exclusions while uniform mode stays active',setup+"BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); BuffTap:Options(); local f=BuffTap.options; f.selectTab(2); f.salvationRecipients.scripts.OnClick(); f.salvationPanel.playerExclusions.scripts.OnClick(); local prior=UnitGUID; UnitGUID=function(u) return u=='party1' and 'Player-new-member' or prior(u) end; BuffTap.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); assert(f.blessingPlayerRows[2].guid=='Player-new-member' and BuffTap.db.blessingPartyMode=='same')")
test('Roster events do not refresh hidden options or unrelated tabs',setup+"BuffTap:Options(); local count=0; local update=BuffTap.UpdateBlessingOptions; BuffTap.UpdateBlessingOptions=function(self,...) count=count+1; return update(self,...) end; BuffTap.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); assert(count==0); BuffTap.options.selectTab(2); BuffTap.options:Hide(); BuffTap.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); assert(count==0)")
test('Old G1 exclusion migrates without broadening party buffing',setup+"BuffTap.db.blessingPartyExcluded=nil; BuffTap.db.raidGroups[1]=false; BuffTap:InitDB(); refresh(); assert(BuffTap.db.blessingPartyExcluded and not BuffTap.action); BuffTap:Options(); assert(not BuffTap.options.blessingGroupEnable.checked)")
test('Enabling party setup explicitly clears migrated party exclusion only',setup+"BuffTap.db.blessingPartyExcluded=true; BuffTap.db.raidGroups[1]=false; BuffTap:Options(); local c=BuffTap.options.blessingGroupEnable; c:SetChecked(true); c.scripts.OnClick(c); assert(not BuffTap.db.blessingPartyExcluded and not BuffTap.db.raidGroups[1]); refresh(); assert(BuffTap.action.key=='bom')")
test('Raid edits cannot clear migrated party exclusion',setup+"BuffTap.db.blessingPartyExcluded=true; BuffTap:Options(); local f=BuffTap.options; f.raidView.scripts.OnClick(); f.blessingGroupEnable:SetChecked(true); f.blessingGroupEnable.scripts.OnClick(f.blessingGroupEnable); assert(BuffTap.db.blessingPartyExcluded)")
test('Recipient filters are accessible without resurrecting the old page',setup+"BuffTap.db.blessingAssignments=false; BuffTap.db.buffGroups.bom={[1]=false}; BuffTap:Options(); local f=BuffTap.options; f.blessingFilterButton.scripts.OnClick(); local p=f.blessingFilters; p.key='bom'; p:Sync(); assert(p.shown and not p.groups[1].checked and not f.assignRows); p.groups[1]:SetChecked(true); p.groups[1].scripts.OnClick(p.groups[1]); assert(BuffTap:GroupSelected(BuffTap:FindBuff('bom'),1))")
test('Recipient class filter edits stay confined to selected blessing',setup+"BuffTap:Options(); BuffTap:ToggleBlessingFilters(); local p=BuffTap.options.blessingFilters; p.key='bom'; p:Sync(); local c=p.classes.PRIEST; c:SetChecked(true); c.scripts.OnClick(c); assert(BuffTap.db.buffClasses.bom.PRIEST and not BuffTap.db.buffClasses.bow)")
test('Filter spell selection keeps the parent dialog open',setup+"BuffTap:Options(); BuffTap:ToggleBlessingFilters(); local p=BuffTap.options.blessingFilters; p.pick.scripts.OnClick(); assert(p.shown and p.pick.menu.shown and BuffTap.options.activeSelector==p); p.pick.menu.rows[3].scripts.OnClick(p.pick.menu.rows[3]); assert(p.shown and p.key=='bow' and not p.pick.menu.shown)")
test('Changing tabs closes filter dialog and its nested selector',setup+"BuffTap:Options(); BuffTap:ToggleBlessingFilters(); local f=BuffTap.options; f.blessingFilters.pick.scripts.OnClick(); f.selectTab(1); assert(not f.blessingFilters.shown and not f.blessingFilters.pick.menu.shown)")
test('One bag event performs exactly one options refresh and no profile snapshot',setup+"BuffTap:Options(); local calls,saves=0,0; local options=BuffTap.Options; local save=BuffTap.SaveClassSetup; BuffTap.Options=function(self,...) calls=calls+1; return options(self,...) end; BuffTap.SaveClassSetup=function(self,...) saves=saves+1; return save(self,...) end; BuffTap.events.scripts.OnEvent(nil,'BAG_UPDATE_DELAYED'); assert(calls==1 and saves==0 and not BuffTap.options.registered.BAG_UPDATE_DELAYED)")
test('Unrelated item completion causes no options refresh',setup+"BuffTap:Options(); local calls=0; local options=BuffTap.Options; BuffTap.Options=function(self,...) calls=calls+1; return options(self,...) end; BuffTap.events.scripts.OnEvent(nil,'ITEM_DATA_LOAD_RESULT',987654321,true); assert(calls==0 and not BuffTap.options.registered.ITEM_DATA_LOAD_RESULT)")
test('Requested item completion refreshes options once',setup+"BuffTap:Options(); BuffTap:RequestItemData(999001); local calls=0; local options=BuffTap.Options; BuffTap.Options=function(self,...) calls=calls+1; return options(self,...) end; BuffTap.events.scripts.OnEvent(nil,'ITEM_DATA_LOAD_RESULT',999001,true); assert(calls==1)")
test('Inventory event refreshes the item picker once',"stock(6888,1248377); BuffTap:Options(); BuffTap:ChooseConsumable(BuffTap:ConsumableFamily('food')); local count=0; local update=BuffTap.UpdateConsumablePicker; BuffTap.UpdateConsumablePicker=function(self,...) count=count+1; return update(self,...) end; BuffTap.events.scripts.OnEvent(nil,'BAG_UPDATE_DELAYED'); assert(count==1 and not BuffTap.itemPicker.registered.BAG_UPDATE_DELAYED)")
test('Forty-player selection does not renormalize initialized plans',raid+"GetNumGroupMembers=function() return 40 end; GetRaidRosterInfo=function(i) return 'Raider',0,math.ceil(i/5) end; BuffTap:InvalidateRoster(); local calls=0; local init=BuffTap.InitBlessingPlans; BuffTap.InitBlessingPlans=function(self,...) calls=calls+1; return init(self,...) end; local action=BuffTap:Select(); assert(action and calls==0)")
test('Malformed non-Paladin plan structure is repaired during matching-class copy',setup+"local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',true); classes.player='DRUID'; BuffTap.profileDB.global.characterSetups[source].Bad={class='DRUID',profile=source,settings={blessingRaidDefaults={classes='bad',priorities='bad'}}}; assert(BuffTap:CopySettingsProfile(source,'Bad')); assert(type(BuffTap.db.blessingRaidDefaults.classes)=='table' and type(BuffTap.db.blessingRaidDefaults.priorities)=='table')")
test('Migrated party exclusion participates in optional same-class copying',setup+"BuffTap.db.blessingPartyExcluded=true; local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',true); BuffTap.db.blessingPartyExcluded=false; assert(BuffTap:CopySettingsProfile(source,BuffTap.profileDB.keys.char)); assert(BuffTap.db.blessingPartyExcluded)")
test('Shared-only profile copy leaves the party exclusion untouched',setup+"local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',true); BuffTap.db.blessingPartyExcluded=true; assert(BuffTap:CopySettingsProfile(source)); assert(BuffTap.db.blessingPartyExcluded)")
test('Paladins no longer construct obsolete per-buff assignment controls',setup+"BuffTap:Options(); assert(not BuffTap.options.assignRows and not BuffTap.options.groupChecks and not BuffTap.options.blessingNeedSlider and BuffTap.options.blessingThreshold)")
test('Other classes no longer construct hidden Paladin controls',"BuffTap:Options(); assert(BuffTap.options.assignRows and not BuffTap.options.blessingRows and not BuffTap.options.blessingThreshold)")
test('Entering Profiles saves one current snapshot',setup+"BuffTap:Options(); local saves=0; local save=BuffTap.SaveClassSetup; BuffTap.SaveClassSetup=function(self,...) saves=saves+1; return save(self,...) end; BuffTap.options.selectTab(8); assert(saves==1)")
test('Excluded party stays excluded in Buffs fallback after raid G1 changes',setup+"BuffTap.db.blessingPartyExcluded=true; BuffTap.db.blessingAssignments=false; BuffTap.db.buffs.bom=true; BuffTap.db.buffs.bok=false; BuffTap.db.buffs.bow=false; BuffTap.db.buffs.bol=false; BuffTap.db.raidGroups[1]=true; aura('player',19740,'Blessing of Might'); refresh(); assert(not BuffTap.action)")
test('Party exclusion cancels an already prepared fallback recipient action',setup+"BuffTap.db.blessingAssignments=false; BuffTap.db.buffs.bok=false; BuffTap.db.buffs.bow=false; BuffTap.db.buffs.bol=false; BuffTap.db.buffs.bom=true; aura('player',19740,'Blessing of Might'); refresh(); assert(BuffTap.action and BuffTap.action.target=='party1'); BuffTap.db.blessingPartyExcluded=true; BuffTap.button.scripts.PreClick(nil,'LeftButton',true); assert(not BuffTap.action)")
print('ALL',len(tests),'SCENARIOS PASSED')
